    e.EntryID = id;
    e.TextureID = texture;
    e.DecalDesc.TextureIndex = blendTexture;
    e.DecalDesc.BlendType = 2;
    e.DecalDesc.Diffuse = 0xffffffffu;
    e.DecalDesc.Specular = 0;
