    t.Decals.push_back(MakeEntry(2, 10, 101));
    t.Decals.push_back(MakeEntry(3, 30, 102));
    t.Decals.push_back(MakeEntry(4, 20, 103));
    t.Decals.push_back(MakeEntry(5, 10, 104));

